// EarningsPreviewCard — compact reusable card with earnings preview generated by AI
// Shows an AI button to generate preview; displays result in AIResultCard

// "Last EPS N/A · Result: Met" before the report existed: the card took the latest quarter whose period had ended
// (Q3 26, ended 30 Sep, not reported yet — epsActual null, epsDifference 0)
// and read difference 0 as "Met". The last quarter is now the latest one
// with an actual EPS, and a result needs both an actual and an estimate.
window.EarningsMath = {
  num(v) {
    if (v == null || v === '') return null;
    const n = typeof v === 'number' ? v : parseFloat(v);
    return Number.isFinite(n) ? n : null;
  },
  lastReported(list, now) {
    const today = window.CalendarDate.today(now || new Date());
    const past = (list || [])
      .filter(e => e && String(e.date || '').slice(0, 10) <= today && window.EarningsMath.num(e.epsActual) != null)
      .sort((a, b) => new Date(b.date) - new Date(a.date));
    return past[0] || null;
  },
  // The next report: the earliest unreported quarter whose report date is
  // today or later (its period end is in the past — Q3 ends 30 Sep, reports
  // 29 Oct — so the period date alone never found it).
  nextReportDate(list, now) {
    const today = window.CalendarDate.today(now || new Date());
    const up = (list || [])
      .filter(e => e && window.EarningsMath.num(e.epsActual) == null)
      .map(e => String(e.reportDate || e.date || '').slice(0, 10))
      .filter(d => d && d >= today)
      .sort();
    return up[0] || null;
  },
  // 'Beat' | 'Miss' | 'Met' | null (no actual or no estimate yet)
  result(q) {
    if (!q) return null;
    const a = window.EarningsMath.num(q.epsActual), e = window.EarningsMath.num(q.epsEstimate);
    if (a == null || e == null) return null;
    const d = +(a - e).toFixed(6);
    return d > 0 ? 'Beat' : d < 0 ? 'Miss' : 'Met';
  },
};

// loadContext (optional): async () => ({ earningsData, fundamentals }), asked
// for when the preview is generated -- a caller that has only the one row
// (the calendar) fetches the quarters and metrics then, not for every card.
window.EarningsPreviewCard = ({ symbol, earningsData, fundamentals, theme, loadContext }) => {
  const C3 = window.C3;
  const isDark = theme === 'dark';

  const [result, setResult] = React.useState(null);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState(null);

  const Icon = ({ name, size = 24, color }) => {
    return React.createElement('svg', { 'aria-hidden': true, focusable: 'false',
      style: { width: size, height: size, flexShrink: 0 },
      viewBox: "0 0 24 24", fill: "none",
      stroke: color || 'currentColor', strokeWidth: "2",
      strokeLinecap: "round", strokeLinejoin: "round"
    }, React.createElement('path', { d: window.IconPaths[name] || "" }));
  };

  // Extract next earnings date if available
  const nextEarningsDate = React.useMemo(() => window.EarningsMath.nextReportDate(earningsData), [earningsData]);

  // Last quarter result
  const lastQuarter = React.useMemo(() => window.EarningsMath.lastReported(earningsData), [earningsData]);
  const lastResult = window.EarningsMath.result(lastQuarter);

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setResult(null);
    window.Haptics?.medium();

    try {
      let quarters = earningsData;
      let metrics = fundamentals;
      if (typeof loadContext === 'function') {
        try {
          const ctx = await loadContext();
          if (ctx && Array.isArray(ctx.earningsData) && ctx.earningsData.length) quarters = ctx.earningsData;
          if (ctx && ctx.fundamentals) metrics = ctx.fundamentals;
        } catch (_) { /* the preview goes ahead on what the card already had */ }
      }
      const response = await window.AIService.getEarningsPreview(symbol, quarters, metrics);
      if (!response || response.trim().length === 0) {
        setError('AI returned an empty response. Please try again.');
      } else {
        setResult(response);
      }
    } catch (err) {
      console.error('EarningsPreview error:', err);
      if (err.message === 'AI_TOKENS_REQUIRED') {
        setError('AI analysis is off. Add OPENAI_API_KEY to .env and restart to enable it.');
      } else {
        setError(window.AIText ? window.AIText.error(err) : (err.message || 'Failed to generate earnings preview'));
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      ...(isDark ? C3.glassDark : C3.glassLight),
      borderRadius: 16, padding: 16,
      border: '1px solid ' + (isDark ? C3.lineDark : C3.lineLight),
    }}>
      {/* Header */}
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        marginBottom: 12,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <div style={{
            width: 32, height: 32, borderRadius: 10,
            background: isDark ? C3.fillDark : C3.fillLight,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            <Icon name="calendar" size={16} color={isDark ? C3.textMutedDark : C3.textMutedLight} />
          </div>
          <div>
            <div style={{
              fontSize: 13, fontWeight: 600,
              color: isDark ? C3.textDark : C3.textLightTheme,
            }}>
              Earnings Preview
            </div>
            <div style={{ fontSize: 11, color: isDark ? C3.textMutedDark : C3.textMutedLight }}>
              {symbol?.split('.')[0] || symbol}
            </div>
          </div>
        </div>
        {nextEarningsDate && (
          <div style={{
            fontSize: 10, fontWeight: 600,
            padding: '3px 8px', borderRadius: 8,
            background: 'rgba(234,179,8,0.15)',
            color: '#eab308',
          }}>
            {window.CalendarDate.format(nextEarningsDate, { month: 'short', day: 'numeric' })}
          </div>
        )}
      </div>

      {/* Last Quarter Mini Summary */}
      {lastQuarter && (
        <div style={{
          display: 'flex', gap: 12, marginBottom: 14,
          padding: 10, borderRadius: 10,
          background: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.02)',
        }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 10, opacity: 0.5, marginBottom: 2 }}>Last EPS</div>
            <div style={{ fontSize: 14, fontWeight: 600 }}>
              {lastQuarter.epsActual != null ? `$${lastQuarter.epsActual}` : 'N/A'}
            </div>
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 10, opacity: 0.5, marginBottom: 2 }}>Estimate</div>
            <div style={{ fontSize: 14, fontWeight: 600 }}>
              {lastQuarter.epsEstimate != null ? `$${lastQuarter.epsEstimate}` : 'N/A'}
            </div>
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 10, opacity: 0.5, marginBottom: 2 }}>Result</div>
            <div style={{
              fontSize: 14, fontWeight: 600,
              color: lastResult === 'Beat' ? C3.success
                : lastResult === 'Miss' ? C3.error
                : (isDark ? C3.textDark : C3.textLightTheme),
            }}>
              {lastResult || 'N/A'}
            </div>
          </div>
        </div>
      )}

      {/* AI Button or Result — the button needs a model key; the numbers above do not. */}
      {window.AIService.getSettings().enabled && !result && !loading && !error && (
        <window.AIFeatureButton
          label="Earnings Preview"
          feature="earnings_preview"
          icon="zap"
          onClick={handleGenerate}
          loading={loading}
          isDark={isDark}
          style={{ width: '100%', justifyContent: 'center' }}
        />
      )}

      {/* Loading State */}
      {loading && (
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          gap: 10, padding: '14px 0',
        }}>
          <div style={{
            width: 16, height: 16,
            border: '2px solid ' + (isDark ? 'rgba(255,255,255,0.2)' : 'rgba(0,0,0,0.1)'),
            borderTopColor: isDark ? C3.textMutedDark : C3.textMutedLight,
            borderRadius: '50%',
            animation: 'spin .8s linear infinite',
          }} />
          <span style={{ fontSize: 13, opacity: 0.6 }}>Analyzing earnings data...</span>
        </div>
      )}

      {/* Error */}
      {error && (
        <div style={{
          padding: 10, borderRadius: 10,
          background: 'rgba(239,68,68,0.1)',
          border: '1px solid rgba(239,68,68,0.2)',
          fontSize: 12, color: C3.error,
          display: 'flex', alignItems: 'center', gap: 6,
          marginBottom: 8,
        }}>
          <Icon name="alertTriangle" size={14} color={C3.error} />
          <span style={{ flex: 1 }}>{error}</span>
          <button
            onClick={handleGenerate}
            style={{
              background: 'none', border: 'none', cursor: 'pointer',
              fontSize: 11, fontWeight: 600, color: isDark ? C3.textDark : C3.textLightTheme,
            }}
          >
            Retry
          </button>
        </div>
      )}

      {/* Result */}
      {result && (
        <window.AIResultCard
          content={result}
          title="Earnings Preview"
          isDark={isDark}
          onDismiss={() => setResult(null)}
        />
      )}
    </div>
  );
};
